function sgi_render_step_icon(string $val, string $title = ''): string {
  $val = trim($val);
  if ($val === '') {
    $val = 'ai';
  }
  if (preg_match('#^https?://#i', $val) || str_starts_with($val, '/')) {
    return '<span class="step-icon has-img"><img src="' . esc_url($val) . '" alt="' . esc_attr($title) . '" loading="lazy"></span>';
  }
  $lib = sgi_icon_library();
  $key = strtolower($val);
  if (isset($lib[$key])) {
    return '<span class="step-icon">' . $lib[$key] . '</span>';
  }
  return '<span class="step-icon">' . $lib['ai'] . '</span>';
}
